import{_ as t,c as o,o as d,a3 as c}from"./chunks/framework.Cc9k46oU.js";const y=JSON.parse('{"title":"SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス","description":"SyncAPIM の未登録シャドウ API 自動検出、OpenAPI 3.0.1 Contract Drift 比較監査、6つの Web・API 攻撃検知ルールおよび8種類の機密情報リアルタイムマスキング体系について説明します。","frontmatter":{"title":"SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス","sidebarTitle":"WAF 脅威検知 & PII マスキング","description":"SyncAPIM の未登録シャドウ API 自動検出、OpenAPI 3.0.1 Contract Drift 比較監査、6つの Web・API 攻撃検知ルールおよび8種類の機密情報リアルタイムマスキング体系について説明します。","head":[["meta",{"name":"keywords","content":"SyncAPIM WAF, シャドウ API, OpenAPI Contract Drift, SQL Injection, XSS, SSRF, RCE, JWT 検証, 個人情報マスキング"}],["meta",{"property":"og:title","content":"SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス"}],["meta",{"property":"og:description","content":"実トラフィックベースの OpenAPI 3.0.1 仕様自動推論、Contract Drift 監査および6つの攻撃・8種類の機密情報保護体系"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncapim/waf-and-pii-governance"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncapim/waf-and-pii-governance"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncapim/waf-and-pii-governance"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス | Empasy Docs"}],["meta",{"property":"og:description","content":"SyncAPIM の未登録シャドウ API 自動検出、OpenAPI 3.0.1 Contract Drift 比較監査、6つの Web・API 攻撃検知ルールおよび8種類の機密情報リアルタイムマスキング体系について説明します。"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/syncapim/waf-and-pii-governance"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス | Empasy Docs"}],["meta",{"name":"twitter:description","content":"SyncAPIM の未登録シャドウ API 自動検出、OpenAPI 3.0.1 Contract Drift 比較監査、6つの Web・API 攻撃検知ルールおよび8種類の機密情報リアルタイムマスキング体系について説明します。"}]],"sort":3},"headers":[],"relativePath":"ja/syncapim/waf-and-pii-governance.md","filePath":"ja/syncapim/waf-and-pii-governance.md","lastUpdated":1795293539000}'),a={name:"ja/syncapim/waf-and-pii-governance.md"};function n(l,e,i,r,s,p){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="syncapim-waf-脅威検知、仕様ドリフト監査および-pii-マスキングガバナンス" tabindex="-1">SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス <a class="header-anchor" href="#syncapim-waf-脅威検知、仕様ドリフト監査および-pii-マスキングガバナンス" aria-label="Permalink to “SyncAPIM WAF 脅威検知、仕様ドリフト監査および PII マスキングガバナンス”">​</a></h1><p><code>SyncAPIM</code> は、単なるシグネチャファイアウォールを超え、<strong>構文トークンフィンガープリント分析器 (<code>SqlXssLexicalTokenizer</code>)</strong>、<strong><code>SyncWatch</code> 連携リアルタイム攻撃パターン検知・ピンポイント仮想パッチ (<code>SandboxedDefenseEvaluator</code>)</strong>、<strong>カーネル eBPF 遮断</strong>、<strong>API インベントリ可視性確保 (Shadow API Discovery)</strong>、<strong>設計仕様に対する実トラフィック整合性検証 (Contract Drift Audit)</strong>、<strong>個人・金融機密情報の漏洩防止 (PII Masking)</strong> を単一パイプラインとして提供します。</p><hr><h2 id="_0-構文トークンフィンガープリント分析器-sqlxsslexicaltokenizer-syncwatch-ピンポイント仮想パッチ-カーネル-ebpf-遮断" tabindex="-1">0. 構文トークンフィンガープリント分析器 (<code>SqlXssLexicalTokenizer</code>) + <code>SyncWatch</code> ピンポイント仮想パッチ + カーネル eBPF 遮断 <a class="header-anchor" href="#_0-構文トークンフィンガープリント分析器-sqlxsslexicaltokenizer-syncwatch-ピンポイント仮想パッチ-カーネル-ebpf-遮断" aria-label="Permalink to “0. 構文トークンフィンガープリント分析器 (SqlXssLexicalTokenizer) + SyncWatch ピンポイント仮想パッチ + カーネル eBPF 遮断”">​</a></h2><ol><li><strong>構文トークンフィンガープリント分析器 (<code>SqlXssLexicalTokenizer</code>)</strong>: <ul><li>従来の不正確なハッシュベースの擬似ベクトル方式を全面的に排除し、3段階の多重デコード（URL、HTML エンティティ、Unicode エスケープ、SQL インラインコメント解除）の後、語彙トークンシーケンスフィンガープリント（<code>s&amp;1</code>、<code>sUE</code>、<code>;k</code>、<code>f(n)</code>、<code>x_script</code>、<code>x_event_handler</code> など）を <code>0.05ms</code> 以内に決定論的に抽出し、亜種 SQLi および XSS 回避攻撃を検知します。</li></ul></li><li><strong><code>SyncWatch</code> 連携リアルタイム攻撃パターン検知およびピンポイント仮想パッチ (<code>ApimDefensePack</code> &amp; <code>SandboxedDefenseEvaluator</code>)</strong>: <ul><li>全社セキュリティ観測所である <a href="/ja/syncwatch/"><code>SyncWatch</code></a> がグローバル脅威フィード（NVD CVE、CISA KEV、OSV.dev、GitHub GHSA、Nuclei、OWASP CRS、KISA）を収集し、コンパイル・検証した <strong><code>ApimDefensePack</code></strong> をリアルタイムで受信します。</li><li><code>SandboxedDefenseEvaluator</code>（<code>SimpleEvaluationContext</code> ベースの隔離評価器）が構文トークンフィンガープリント、ターゲット位置別正規表現（<code>HEADER</code>、<code>URI</code>、<code>QUERY</code>、<code>BODY</code>）、Restricted SpEL 式を組み合わせて評価し、サーバー再起動なしで特定エンドポイントにピンポイント仮想パッチを即時適用します。</li></ul></li><li><strong>カーネル eBPF 超低遅延遮断</strong>: <ul><li>高リスクの侵害試行が確認された攻撃元 IP および異常パケットは、L7 ゲートウェイ遮断と同時にカーネル eBPF (XDP/TC) レイヤーで即時ドロップし、バックエンドリソースの枯渇を未然に防止します。</li></ul></li></ol><hr><h2 id="_1-未登録シャドウ-api-自動検出および-openapi-3-0-1-推論" tabindex="-1">1. 未登録シャドウ API 自動検出および OpenAPI 3.0.1 推論 <a class="header-anchor" href="#_1-未登録シャドウ-api-自動検出および-openapi-3-0-1-推論" aria-label="Permalink to “1. 未登録シャドウ API 自動検出および OpenAPI 3.0.1 推論”">​</a></h2><ol><li><strong>実トラフィックベースのエンドポイントカタログ自動生成</strong>: <ul><li><code>sync-apim-detector</code> の <code>DetectionRuleServiceImpl</code> は、受信した HTTP パケットの <code>host</code>、<code>method</code>、<code>path</code> の組み合わせを分析し、未登録エンドポイントを <code>wapf_api_endpoint</code> および <code>wapf_api_endpoint_detail</code> に自動登録します。</li><li>リクエストクエリ文字列、リクエストボディ (JSON)、レスポンスボディ (JSON) のすべてのフィールドを再帰的に解析し、<code>wapf_data_field</code> にデータ型と JSONPath（<code>$.data.accountNo</code> など）を記録します。</li></ul></li><li><strong>OpenAPI 3.0.1 仕様のリアルタイム合成および Contract Drift 比較監査</strong>: <ul><li>観測された入出力フィールドをもとに、標準 OpenAPI 3.0.1 JSON 仕様（<code>wapf_open_api_spec</code>）を自動合成します。</li><li><code>POST /api/v1/apim/spec/audit</code> (<code>WapfOpenApiSpecServiceImpl.auditContractDrift</code>) 呼び出し時、設計仕様（<code>designSpec</code>）と実トラフィック仕様を比較し、次の3種類のドリフトを判別します。 <ul><li><strong><code>UNDOCUMENTED_RESPONSE_FIELD</code></strong>: 設計仕様に定義されていない内部フィールドや機密フィールドが実際の API レスポンスとして露出している場合</li><li><strong><code>MISSING_REQUIRED_PARAM</code></strong>: 設計上必須のリクエストパラメータが欠落したまま呼び出されている場合</li><li><strong><code>SHADOW_ENDPOINT</code></strong>: 承認された API 仕様書に存在しない未登録のデバッグ・レガシーエンドポイントが呼び出されている場合</li></ul></li></ul></li></ol><hr><h2 id="_2-6つの標準-web・api-脅威検知ルール-wapf-rule" tabindex="-1">2. 6つの標準 Web・API 脅威検知ルール (<code>wapf_rule</code>) <a class="header-anchor" href="#_2-6つの標準-web・api-脅威検知ルール-wapf-rule" aria-label="Permalink to “2. 6つの標準 Web・API 脅威検知ルール (wapf_rule)”">​</a></h2><p><code>db/04_seed_domain.sql</code> に標準搭載された6つのコア脅威検知ルールは、リクエスト URL、ヘッダー、クエリ、ボディ全体を対象にリアルタイム正規表現マッチングおよび JWT 構造検証を実行します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">ルール ID</th><th style="text-align:left;">脅威検知ルール名称</th><th style="text-align:center;">重大度</th><th style="text-align:left;">主な検知パターンおよび防御対象</th></tr></thead><tbody><tr><td style="text-align:left;"><code>rule_apim_001</code></td><td style="text-align:left;"><strong>SQL インジェクション攻撃検知</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>UNION SELECT</code>、<code>OR 1=1</code>、<code>DROP TABLE</code>、<code>SLEEP()</code>、<code>WAITFOR DELAY</code> などの DB 操作構文</td></tr><tr><td style="text-align:left;"><code>rule_apim_002</code></td><td style="text-align:left;"><strong>クロスサイトスクリプティング検知</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;"><code>&lt;script&gt;</code>、<code>javascript:</code>、<code>onerror=</code>、<code>onload=</code> などの悪性スクリプト挿入</td></tr><tr><td style="text-align:left;"><code>rule_apim_003</code></td><td style="text-align:left;"><strong>サーバーサイドリクエストフォージェリ検知</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>169.254.169.254</code>（クラウドメタデータ）、<code>localhost</code>、<code>127.0.0.1</code>、<code>file://</code>、<code>gopher://</code> 内部ネットワーク探索</td></tr><tr><td style="text-align:left;"><code>rule_apim_004</code></td><td style="text-align:left;"><strong>リモートコマンド実行攻撃検知</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>; cat /etc/passwd</code>、<code>| bash</code>、<code>`whoami`</code>、<code>cmd.exe</code>、<code>powershell</code> などの OS コマンドインジェクション</td></tr><tr><td style="text-align:left;"><code>rule_apim_005</code></td><td style="text-align:left;"><strong>ディレクトリトラバーサル検知</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;"><code>../</code>、<code>..\\\\</code>、<code>/etc/passwd</code>、<code>win.ini</code>、URL エンコードされた上位パス回避アクセス</td></tr><tr><td style="text-align:left;"><code>rule_apim_006</code></td><td style="text-align:left;"><strong>JWT トークン整合性および署名検証</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>alg: &quot;none&quot;</code> 署名回避攻撃、期限切れトークン（<code>exp</code> 超過）、異常ペイロード構造改ざん</td></tr></tbody></table><hr><h2 id="_3-7つのセキュリティポリシーグループ-wapf-policy-およびリアルタイム-redis-キャッシュ同期" tabindex="-1">3. 7つのセキュリティポリシーグループ (<code>wapf_policy</code>) およびリアルタイム Redis キャッシュ同期 <a class="header-anchor" href="#_3-7つのセキュリティポリシーグループ-wapf-policy-およびリアルタイム-redis-キャッシュ同期" aria-label="Permalink to “3. 7つのセキュリティポリシーグループ (wapf_policy) およびリアルタイム Redis キャッシュ同期”">​</a></h2><p>管理コンソール（<code>/waf/policy</code>）でセキュリティポリシーやルールマッピングを変更すると、<code>WapfPolicyServiceImpl.syncPolicyRuleCache()</code> が即時実行されて Redis（<code>wapf:policy:rules</code>）を更新し、<code>sync-apim-detector</code> を再起動することなくリアルタイム検知パイプラインへ即座に反映されます。</p><ul><li><strong><code>pol_apim_001</code> (認証セキュリティポリシー)</strong>: デフォルト（<code>basic=true</code>）グローバル保護ポリシー</li><li><strong><code>pol_apim_002</code> (アクセス制御ポリシー)</strong>: 管理者および内部精算 API アクセス統制</li><li><strong><code>pol_apim_003</code> (データ暗号化ポリシー)</strong>: 金融・決済区間の転送データ保護</li><li><strong><code>pol_apim_004</code> (権限認可ポリシー)</strong>: BOLA/IDOR オブジェクトレベル権限検証</li><li><strong><code>pol_apim_005</code> (ネットワークセキュリティポリシー)</strong>: 外部コールバックおよび Webhook SSRF 防御</li><li><strong><code>pol_apim_006</code> (個人情報保護ポリシー)</strong>: 顧客マイデータ照会 API 集中監視</li><li><strong><code>pol_apim_007</code> (侵入検知ポリシー)</strong>: 高リスク RCE・SQLi ペイロード即時遮断</li></ul><hr><h2 id="_4-8種類の個人・金融機密情報-pii-リアルタイムマスキング-wapf-sensitivity" tabindex="-1">4. 8種類の個人・金融機密情報 (PII) リアルタイムマスキング (<code>wapf_sensitivity</code>) <a class="header-anchor" href="#_4-8種類の個人・金融機密情報-pii-リアルタイムマスキング-wapf-sensitivity" aria-label="Permalink to “4. 8種類の個人・金融機密情報 (PII) リアルタイムマスキング (wapf_sensitivity)”">​</a></h2><p>API リクエストおよびレスポンスに含まれる個人情報がログや外部レスポンスへ平文のまま露出しないよう、8種類の機密情報正規表現をリアルタイムでスキャンしてマスキング（<code>***</code>）処理し、該当フィールドを <code>wapf_data_field.sensitivity_uuid</code> に自動タグ付けします。</p><table tabindex="0"><thead><tr><th style="text-align:left;">識別子</th><th style="text-align:left;">機密情報項目</th><th style="text-align:center;">重大度</th><th style="text-align:left;">検知対象フォーマット概要</th></tr></thead><tbody><tr><td style="text-align:left;"><code>sens_apim_001</code></td><td style="text-align:left;"><strong>口座番号</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">市中銀行口座番号フォーマット（<code>\\d{3,4}-\\d{2,6}-\\d{4,6}</code>）</td></tr><tr><td style="text-align:left;"><code>sens_apim_002</code></td><td style="text-align:left;"><strong>メールアドレス</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">標準メールアドレスフォーマット</td></tr><tr><td style="text-align:left;"><code>sens_apim_003</code></td><td style="text-align:left;"><strong>カード番号</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">16桁のクレジット・デビットカード番号（<code>\\d{4}-\\d{4}-\\d{4}-\\d{4}</code>）</td></tr><tr><td style="text-align:left;"><code>sens_apim_004</code></td><td style="text-align:left;"><strong>住民登録番号</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;">13桁の住民登録番号および外国人登録番号（<code>\\d{6}-[1-4]\\d{6}</code>）</td></tr><tr><td style="text-align:left;"><code>sens_apim_005</code></td><td style="text-align:left;"><strong>氏名</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">JSON フィールド内の氏名識別パターン</td></tr><tr><td style="text-align:left;"><code>sens_apim_006</code></td><td style="text-align:left;"><strong>パスワード</strong></td><td style="text-align:center;"><code>4</code> (Critical)</td><td style="text-align:left;"><code>password</code>、<code>passwd</code>、<code>pwd</code>、<code>secret</code> キー・バリュー平文露出</td></tr><tr><td style="text-align:left;"><code>sens_apim_007</code></td><td style="text-align:left;"><strong>IP アドレス</strong></td><td style="text-align:center;"><code>2</code> (Medium)</td><td style="text-align:left;">内部ネットワークおよびクライアント IPv4 アドレスフォーマット</td></tr><tr><td style="text-align:left;"><code>sens_apim_008</code></td><td style="text-align:left;"><strong>電話番号</strong></td><td style="text-align:center;"><code>3</code> (High)</td><td style="text-align:left;">携帯電話および一般電話番号（<code>01[016789]-\\d{3,4}-\\d{4}</code>）</td></tr></tbody></table>',20)])])}const f=t(a,[["render",n]]);export{y as __pageData,f as default};
